xhtml:div.xhtml:script:
(async()=>{
  const frame=document.getElementById('app');
  const source='https://cdn.jsdelivr.net/gh/m6788928-byte/yoyolov@main/index.html';
  const escapeHTML=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  try{
    const response=await fetch(source,{cache:'no-store'});
    if(!response.ok) throw new Error('HTTP '+response.status);
    let html=await response.text();
    if(!/<head(?:\\s[^>]*)?>/i.test(html)) throw new Error('The site HTML has no head element');
    html=html.replace(/<head([^>]*)>/i,'<head$1><base href="https://cdn.jsdelivr.net/gh/m6788928-byte/yoyolov@main/">');
    const doc=frame.contentDocument;
    doc.open();doc.write(html);doc.close();
  }catch(error){
    const doc=frame.contentDocument;
    doc.open();
    doc.write('<!doctype html><meta charset="utf-8"><style>body{margin:0;padding:28px;background:#111214;color:#ddd;font:14px system-ui,sans-serif}h2{font-size:18px}p{margin-top:10px;color:#aaa}</style><h2>Yoyolov could not load</h2><p>The browser blocked the content source or the request failed.</p><p>'+escapeHTML(error.message)+'</p>');
    doc.close();
  }
})();
